// CrowdStrike CQL for MFA Method Switch Before High-Value Transaction
// Repository: flame-banking-identity-management
// Correlates MFA downgrade with subsequent high-value transaction
// within 4h for the same account
(event_type="MFA_METHOD_CHANGE" AND
  (new_mfa_method="sms_otp" OR new_mfa_method="email_otp" OR new_mfa_method="voice_call"))
OR ((event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT") AND
  transaction_amount>=5000)
| selfJoinFilter(account_id, where=[
    {event_type="MFA_METHOD_CHANGE"}
    {event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT"}
  ])
| groupBy(account_id, function=[
    count(as=event_count),
    collect([event_type, new_mfa_method, transaction_amount, @timestamp])
  ], span=4h)
| event_count >= 2
